ga3b(){return"\u05d4\u05e4\u05e0\u05d9\u05d9\u05d4 \u05d4\u05ea\u05e7\u05d1\u05dc\u05d4"},
ga3a(){return"\u05d4\u05e4\u05e0\u05d9\u05d9\u05d4 \u05e0\u05e9\u05de\u05e8\u05d4. \u05e9\u05de\u05e8\u05d5 \u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05e4\u05e0\u05d9\u05d9\u05d4 \u05d5\u05e6\u05d9\u05d9\u05e0\u05d5 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05db\u05dc \u05e4\u05e0\u05d9\u05d9\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea \u05dc\u05ea\u05de\u05d9\u05db\u05d4"},
ga38(){return"\u05de\u05e1\u05e4\u05e8 \u05d4\u05e4\u05e0\u05d9\u05d9\u05d4"},
ga30(){return"\u05e4\u05e0\u05d9\u05d9\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea"},
ga2i(){return"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05e7\u05e9 \u05de\u05d7\u05d9\u05e7\u05d4 \u05de\u05dc\u05d0\u05d4 \u05e9\u05dc \u05d4\u05d7\u05e9\u05d1\u05d5\u05df \u05d2\u05dd \u05d1\u05dc\u05d9 \u05d4\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d4. \u05e0\u05e9\u05dc\u05d7 \u05e7\u05d5\u05d3 \u05d1-SMS \u05dc\u05de\u05e1\u05e4\u05e8 \u05e9\u05dc \u05d4\u05d7\u05e9\u05d1\u05d5\u05df \u05db\u05d3\u05d9 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05d6\u05d4 \u05d0\u05ea\u05dd"},
gxM(){return"\u05de\u05d4 \u05d9\u05e7\u05e8\u05d4"},
